31	export async function generate(input: {
32	  occasion: UiOccasion;
33	  formality: number | null;
34	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
35	  lean: string[];
36	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
37	  regenerate?: boolean;
38	  city?: { lat: number; lon: number; label: string; source: LocationSource };
39	}): Promise<GenerateResult> {
40	  try {
41	    const supabase = await createClient();
42	    const {
43	      data: { user },
44	    } = await supabase.auth.getUser();
45	    if (!user) return { status: "error", message: "Not signed in" };
46	
47	    const { data: profile } = await supabase
48	      .from("profiles")
49	      .select(
50	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source",
51	      )
52	      .eq("id", user.id)
53	      .single();
54	    const { data: itemsRaw } = await supabase
55	      .from("items")
56	      .select("*")
57	      .eq("user_id", user.id)
58	      .eq("archived", false);
59	    const items = itemsRaw ?? [];
60	    const byId = new Map(items.map((i) => [i.id, i]));
61	
62	    const loc = resolveLocation({ input: input.city, profile });
63	
64	    const now = new Date();
65	    const f = await fetchForecast(loc.lat, loc.lon);
66	    const advice = laterAdvice(f.hourly);
67	    const weather: WeatherPayload = {
68	      tempC: f.tempC,
69	      feelsLikeC: f.feelsLikeC,
70	      condition: f.condition,
71	      cityLabel: loc.label,
72	      timezone: f.timezone,
73	      locationOrigin: loc.origin,
74	      laterSentence: advice.sentence,
75	      adviceClause: advice.adviceClause,
76	      laterLabel: "Later",
77	      hourly: f.hourly,
78	    };
79	
80	    const today = localDateFor(now, f.timezone);
81	
82	    // The daily drop (Decision 5): today's looks are generated once and then
83	    // read back. Only an explicit regenerate spends an AI call on a day the
84	    // stylist has already answered.
85	    if (!input.regenerate) {
86	      const stored = await loadDailyLooks(user.id, input.occasion, today);
87	      if (stored?.length) {
88	        const paths = Array.from(
89	          new Set(
90	            stored
91	              .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
92	              .filter((it): it is NonNullable<typeof it> => Boolean(it))
93	              .map((it) => displayPath(it)),
94	          ),
95	        );
96	        const signed = await signItemImages(paths);
97	        const looks = reassembleLooks(stored, byId, signed, (id) => {
98	          const it = byId.get(id);
99	          return it ? displayPath(it) : undefined;
100	        });
101	        // null = the closet changed under the stored set; fall through and
102	        // regenerate rather than showing an outfit with a hole in it.
103	        if (looks) return { status: "ok", weather, looks };
104	      }
105	    }
106	
107	    await assertCanGenerate(user.id);
108	
109	    const candItems: CandidateItem[] = items.map((i) => ({
110	      id: i.id,
111	      category: i.category,
112	      colors: i.colors ?? [],
113	      formality: i.formality,
114	      seasons: i.seasons ?? [],
115	      material: i.material,
116	    }));
117	    // Occasion gives the context; the user's onboarding dress codes narrow it;
118	    // an explicit Refine formality overrides both.
119	    const band = applyFormalityOverride(
120	      personalBand(input.occasion, profile),
121	      input.formality,
122	    );
123	    const candidateArgs = {
124	      band,
125	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
126	      season: currentSeason(now),
127	      excludeItemIds: [],
128	      maxAccessories: 1,
129	    };
130	    const combos = buildCandidates(candItems, candidateArgs);
131	    if (combos.length === 0) {
132	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
133	    }
134	
135	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
136	    // The Refine colour pick lands here, in ranking — not in candidate building.
137	    // It reorders the shortlist toward the requested families and is dropped
138	    // silently when the closet cannot honour it.
139	    const top = rankTopN(combos, { aesthetic, band, lean: input.lean }, 20);
140	
141	    const { picks } = await rerank({
142	      combos: top.map((t) =>
143	        t.items.map((ci) => {
144	          const it = byId.get(ci.id)!;
145	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
146	        }),
147	      ),
148	      aesthetic,
149	      occasion: input.occasion,
150	      weatherLabel: f.condition,
151	      tempC: f.tempC,
152	    });
153	
154	    const paths = Array.from(
155	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
156	    );
157	    const signed = await signItemImages(paths);
158	
159	    const looks: Look[] = picks.map((p) => {
160	      const combo = top[p.combo_index]?.items ?? top[0].items;
161	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
162	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
163	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
164	        itemId: d.id,
165	        category: d.category,
166	        subcategory: d.subcategory ?? null,
167	        brand: d.brand ?? null,
168	        name: d.name ?? null,
169	        colors: d.colors ?? [],
170	        cutoutUrl: signed.get(displayPath(d)) ?? "",
171	        slot: slots[idx],
172	      }));
173	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
174	    });
175	
176	    // Fire-and-forget would be simpler, but a failed write means the user pays
177	    // for another AI call on their next tap — worth awaiting.
178	    await saveDailyLooks(user.id, input.occasion, today, weather, looks);
179	
180	    return { status: "ok", weather, looks };
181	  } catch (e) {
182	    console.error("[generate] failed:", e);
183	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
184	  }
185	}
