188	 * The single write path for a user's location. `generate` stays read-only.
189	 * Called by the client after a successful generate for a location the user
190	 * actually supplied (geolocation or city search) — never for the profile or
191	 * default fallback, where there is nothing new to write.
192	 */
193	export async function saveLocation(input: unknown): Promise<void> {
194	  const d = LocationInputSchema.parse(input);
195	
196	  const supabase = await createClient();
197	  const {
198	    data: { user },
199	  } = await supabase.auth.getUser();
200	  if (!user) return;
201	
202	  await supabase
203	    .from("profiles")
204	    .update({
205	      location_lat: roundCoord(d.lat),
206	      location_lon: roundCoord(d.lon),
207	      location_label: d.label,
208	      location_source: d.source,
209	      location_timezone: d.timezone,
210	      location_updated_at: new Date().toISOString(),
211	    })
212	    .eq("id", user.id);
213	}
